// TestTables.cs
// -----------------------------------------------------------------------------
// Contains unit tests for verifying storage functionality within the Bohris test suite.
// -----------------------------------------------------------------------------
namespace Bovis.Data.Bohris.Test
{
    /// <summary>
    /// Test class containing unit tests for table-related functionality.
    /// Inherits common test setup from <see cref="Bovis.TestProfile.TestClassCommon"/>.
    /// </summary>
    /// <remarks>
    /// This class is part of the Bohris test suite and focuses on validating
    /// storage interactions related to table handling.
    /// </remarks>
    [TestClass]
    public class TestTables : Bovis.TestProfile.TestClassCommon
    {
        /// <summary>
        /// Tests that opening an in-memory storage file returns the default storage instance.
        /// </summary>
        /// <remarks>
        /// The test opens a storage file using the special ":memory:" identifier,
        /// which creates an in‑memory SQLite database. The expectation is that the
        /// storage system returns the singleton <c>DefaultStorage</c> instance.
        /// </remarks>
        [TestMethod]
        public void TestKeyHydrostrat()
        {
            // Open an in-memory storage file with write access.
            // The storage system should resolve this to the default singleton storage.
            using var s = Bovis.Storage.Storage.OpenStorageFile(":memory:", true);
            // Verify that the returned storage instance matches the default storage.
            Assert.AreEqual(Bovis.Storage.Storage.DefaultStorage, s);
        }
    }
}
